/// <summary>
///   Class for <c>METRetailCDXSeedBaseEventHandler</c> methods.
/// </summary>
internal final class METRetailCDXSeedBaseEventHandler
{
}

Method.Source:
/// <summary>
///  Subscribes to delegate to get the extension CDX seed data job and subjob definitions.
/// </summary>
/// <param name = "originalCDXSeedDataResource">The resource str of the CDX seed data that is being extended.</param>
/// <param name = "resources">Resource list objet that is used to return the CDX seed data extension resource str retrieved using resourceStr function.
/// Add the CDX seed data extension resource name to this object.</param>
/// <remarks> Should check if the original CDX seed data resource name argument matches the resource name of the seed data that
/// is being extended before adding the name of the extension resource string to the resources list object.</remarks>
[SubscribesTo(classStr(RetailCDXSeedDataBase), delegateStr(RetailCDXSeedDataBase, registerCDXSeedDataExtension))]
public static void RetailCDXSeedDataBase_registerCDXSeedDataExtension(str originalCDXSeedDataResource, List resources)
{
    if (originalCDXSeedDataResource == resourceStr(RetailCDXSeedDataAX7))
    {
        resources.addEnd(resourceStr(METRetailCDXSeedDataAX7));
    }
}
